"""Second batch of starter parts (library v2). Specs are typical; confirm with the datasheet.

SMD top markings are manufacturer dependent: only well-established ones are listed.
"""


def P(pn, cat, desc, pkg="", specs="", marks=(), notes=""):
    return dict(pn=pn, cat=cat, desc=desc, pkg=pkg, specs=specs, marks=list(marks), notes=notes)


